WITH filtered AS (SELECT *, INITCAP(TRIM(location)) AS location_title, CASE WHEN dept_name = 'Engineering' THEN 1 ELSE 0 END AS is_engineering, COALESCE(dept_name, 'NONE') AS dept_name_clean FROM departments WHERE location IS NOT NULL) SELECT s.*, top1.salary, top1.level FROM filtered s JOIN LATERAL (SELECT c.salary, c.level FROM employees c WHERE c.dept_id = s.id ORDER BY c.salary DESC, c.id DESC LIMIT 1) top1 ON TRUE;
